    "examTag": "Punjab Master Cadre Science (Level H)",
    "question": {
      "en": "In Lassaigne’s sodium fusion extract test for an organic compound, what is the chemical formula of the Prussian blue precipitate formed when nitrogen alone is present, and what blood-red complex is formed when both nitrogen and sulphur are present together?",
      "pa": "ਇੱਕ ਕਾਰਬਨਿਕ ਯੋਗਿਕ ਲਈ ਲੇਸਾਇਨ (Lassaigne) ਦੇ ਸੋਡੀਅਮ ਫਿਊਜ਼ਨ ਟੈਸਟ ਵਿੱਚ, ਜਦੋਂ ਕੇਵਲ ਨਾਈਟ੍ਰੋਜਨ ਮੌਜੂਦ ਹੋਵੇ ਤਾਂ ਬਣਨ ਵਾਲੇ ਪਰਸ਼ੀਅਨ ਬਲੂ (Prussian blue) ਅਵਖੇਪ ਦਾ ਰਸਾਇਣਕ ਸੂਤਰ ਕੀ ਹੈ, ਅਤੇ ਜਦੋਂ ਨਾਈਟ੍ਰੋਜਨ ਅਤੇ ਸਲਫਰ ਦੋਵੇਂ ਮੌਜੂਦ ਹੋਣ ਤਾਂ ਕਿਹੜਾ ਖੂਨ-ਲਾਲ (blood-red) ਕੰਪਲੈਕਸ ਬਣਦਾ ਹੈ?",
      "hi": "किसी कार्बनिक यौगिक के लेसाइन (Lassaigne) सोडियम संगलन परीक्षण में, केवल नाइट्रोजन उपस्थित होने पर बनने वाले प्रशियन ब्लू (Prussian blue) यौगिक का सूत्र क्या है, और नाइट्रोजन व सल्फर दोनों साथ होने पर कौन-सा रक्त-लाल (blood-red) संकुल बनता है?"
    },
    "options": {
      "A": {
        "en": "Prussian blue: Fe₄[Fe(CN)₆]₃ (Ferriferrocyanide); Blood-red: [Fe(SCN)]²⁺ (Ferric thiocyanate)",
        "pa": "ਪਰਸ਼ੀਅਨ ਬਲੂ: Fe₄[Fe(CN)₆]₃ (ਫੈਰੀਫੈਰੋਸਾਇਨਾਈਡ); ਖੂਨ-ਲਾਲ: [Fe(SCN)]²⁺ (ਫੈਰਿਕ ਥਾਇਓਸਾਇਨੇਟ)",
        "hi": "प्रशियन ब्लू: Fe₄[Fe(CN)₆]₃ (फेरीफेरोसायनाइड); रक्त-लाल: [Fe(SCN)]²⁺ (फेरिक थायोसायनेट)"
      },
      "B": {
        "en": "Prussian blue: K₂Fe[Fe(CN)₆]; Blood-red: [Fe(CN)₅NO]²⁻ (Nitroprusside)",
        "pa": "ਪਰਸ਼ੀਅਨ ਬਲੂ: K₂Fe[Fe(CN)₆]; ਖੂਨ-ਲਾਲ: [Fe(CN)₅NO]²⁻ (ਨਾਈਟ੍ਰੋਪਰੂਸਾਈਡ)",
        "hi": "प्रशियन ब्लू: K₂Fe[Fe(CN)₆]; रक्त-लाल: [Fe(CN)₅NO]²⁻ (नाइट्रोप्रुसाइड)"
      },
      "C": {
        "en": "Prussian blue: Fe₃[Fe(CN)₆]₂ (Turnbull’s blue); Blood-red: Fe₂S₃",
        "pa": "ਪਰਸ਼ੀਅਨ ਬਲੂ: Fe₃[Fe(CN)₆]₂ (ਟਰਨਬੁੱਲ ਬਲੂ); ਖੂਨ-ਲਾਲ: Fe₂S₃",
        "hi": "प्रशियन ब्लू: Fe₃[Fe(CN)₆]₂ (टर्नबुल ब्लू); रक्त-लाल: Fe₂S₃"
      },
      "D": {
        "en": "Prussian blue: Na₄[Fe(CN)₆]; Blood-red: Na₂[Fe(CN)₅NOS]",
        "pa": "ਪਰਸ਼ੀਅਨ ਬਲੂ: Na₄[Fe(CN)₆]; ਖੂਨ-ਲਾਲ: Na₂[Fe(CN)₅NOS]",
        "hi": "प्रशियन ब्लू: Na₄[Fe(CN)₆]; रक्त-लाल: Na₂[Fe(CN)₅NOS]"
      }
    },
    "correct": "A",
    "explanation": {
      "en": "In Lassaigne’s test, Na + C + N → NaCN. Boiling with FeSO₄ forms Na₄[Fe(CN)₆], which reacts with Fe³⁺ (formed on acidification) to yield Prussian blue, Iron(III) hexacyanoferrate(II), Fe₄[Fe(CN)₆]₃. When both N and S are present, Na + C + N + S → NaSCN, which reacts with Fe³⁺ to give a blood-red coloration due to [Fe(SCN)]²⁺ / [Fe(SCN)(H₂O)₅]²⁺.",
      "pa": "ਲੇਸਾਇਨ ਟੈਸਟ ਵਿੱਚ ਕੇਵਲ ਨਾਈਟ੍ਰੋਜਨ ਹੋਣ ਤੇ ਆਇਰਨ(III) ਹੈਕਸਾਸਾਇਨੋਫੈਰੇਟ(II) ਅਰਥਾਤ Fe₄[Fe(CN)₆]₃ (Prussian blue) ਬਣਦਾ ਹੈ। ਜਦੋਂ N ਅਤੇ S ਦੋਵੇਂ ਮੌਜੂਦ ਹੋਣ, ਤਾਂ NaSCN ਬਣਦਾ ਹੈ ਜੋ Fe³⁺ ਨਾਲ ਕਿਰਿਆ ਕਰਕੇ ਖੂਨ ਵਰਗਾ ਲਾਲ [Fe(SCN)]²⁺ ਬਣਾਉਂਦਾ ਹੈ।",
      "hi": "लेसाइन परीक्षण में केवल नाइट्रोजन होने पर आयरन(III) हेक्सासायनोफेरेट(II) अर्थात् Fe₄[Fe(CN)₆]₃ (प्रशियन ब्लू) बनता है। जब N और S दोनों उपस्थित होते हैं, तो NaSCN बनता है जो Fe³⁺ के साथ रक्त-लाल [Fe(SCN)]²⁺ संकुल देता है।"
    },
