        "pa": "ਉੱਪਰਲਾ ਮੈਨਿਸਕਸ ਪੜ੍ਹਿਆ ਜਾਂਦਾ ਹੈ ਕਿਉਂਕਿ KMnO₄ ਅਪਾਰਦਰਸ਼ੀ ਹੈ; KMnO₄ ਸਵੈ-ਸੂਚਕ (self-indicator) ਵਜੋਂ ਕੰਮ ਕਰਦਾ ਹੈ",
