      "pa": "ਗੂੜ੍ਹੇ ਬੈਂਗਣੀ ਰੰਗ ਦੇ KMnO₄ ਘੋਲ ਵਿੱਚ ਹੇਠਲਾ ਮੈਨਿਸਕਸ ਦਿਖਾਈ ਨਹੀਂ ਦਿੰਦਾ, ਇਸ ਲਈ ਹਮੇਸ਼ਾ ਉੱਪਰਲਾ ਮੈਨਿਸਕਸ (upper meniscus) ਪੜ੍ਹਿਆ ਜਾਂਦਾ ਹੈ। KMnO₄ ਖੁਦ ਸਵੈ-ਸੂਚਕ (self-indicator) ਵਜੋਂ ਕੰਮ ਕਰਦਾ ਹੈ।",
