    "id": "q-mc-sci-opt-6",
    "topicId": "sci-phy-waves-optics",
    "subjectId": "science",
    "examId": "punjab-master-cadre-science",
    "examTag": "Punjab Master Cadre Science (Level H)",
    "question": {
      "en": "In a Young’s Double Slit Experiment (YDSE), monochromatic light of wavelength λ = 600 nm illuminates two slits separated by d = 0.5 mm, and the screen is placed at D = 1.5 m from the slits. What is the fringe width (β)?",
      "pa": "ਯੰਗ ਦੇ ਡਬਲ ਸਲਿਟ ਪ੍ਰਯੋਗ (YDSE) ਵਿੱਚ, ਤਰੰਗ ਲੰਬਾਈ λ = 600 nm ਵਾਲਾ ਇੱਕ-ਰੰਗੀ ਪ੍ਰਕਾਸ਼ d = 0.5 mm ਦੀ ਦੂਰੀ ਤੇ ਸਥਿਤ ਦੋ ਸਲਿਟਾਂ ਤੇ ਪੈਂਦਾ ਹੈ, ਅਤੇ ਪਰਦਾ ਸਲਿਟਾਂ ਤੋਂ D = 1.5 m ਦੀ ਦੂਰੀ ਤੇ ਰੱਖਿਆ ਗਿਆ ਹੈ। ਫ੍ਰਿੰਜ ਚੌੜਾਈ (β) ਕਿੰਨੀ ਹੈ?",
      "hi": "यंग के द्वि-झिरी प्रयोग (YDSE) में, तरंगदैर्घ्य λ = 600 nm का एकवर्णी प्रकाश d = 0.5 mm की दूरी पर स्थित दो झिरियों पर आपतित होता है, तथा पर्दा झिरियों से D = 1.5 m की दूरी पर रखा है। फ्रिंज चौड़ाई (β) क्या है?"
    },
    "options": {
      "A": {
        "en": "0.9 mm",
        "pa": "0.9 mm",
        "hi": "0.9 mm"
      },
      "B": {
        "en": "1.2 mm",
        "pa": "1.2 mm",
        "hi": "1.2 mm"
      },
      "C": {
        "en": "2.4 mm",
        "pa": "2.4 mm",
        "hi": "2.4 mm"
      },
      "D": {
        "en": "1.8 mm",
        "pa": "1.8 mm",
        "hi": "1.8 mm"
      }
    },
    "correct": "D",
    "explanation": {
      "en": "Fringe width in YDSE is β = λD / d. Substituting λ = 600 × 10⁻⁹ m, D = 1.5 m, and d = 0.5 × 10⁻³ m: β = (600 × 10⁻⁹ × 1.5) / (0.5 × 10⁻³) = 600 × 10⁻⁹ × 3 × 10³ = 1.8 × 10⁻³ m = 1.8 mm.",
      "pa": "YDSE ਵਿੱਚ ਫ੍ਰਿੰਜ ਚੌੜਾਈ ਦਾ ਸੂਤਰ β = λD / d ਹੈ। ਮੁੱਲ ਰੱਖਣ ਤੇ: β = (600 × 10⁻⁹ m × 1.5 m) / (0.5 × 10⁻³ m) = 1.8 × 10⁻³ m = 1.8 mm।",
      "hi": "YDSE में फ्रिंज चौड़ाई का सूत्र β = λD / d है। मान रखने पर: β = (600 × 10⁻⁹ m × 1.5 m) / (0.5 × 10⁻³ m) = 1.8 × 10⁻³ m = 1.8 mm।"
    },
