    "question": {
      "en": "A reversible Carnot heat engine operates between a hot source at 327°C and a cold sink at 27°C. If the engine absorbs 1200 J of heat per cycle from the source, how much mechanical work (W) does it perform per cycle and what is its thermal efficiency (η)?",
      "pa": "ਇੱਕ ਉਤਕ੍ਰਮਣੀ ਕਾਰਨੋਟ ਤਾਪ ਇੰਜਣ 327°C ਵਾਲੇ ਗਰਮ ਸਰੋਤ ਅਤੇ 27°C ਵਾਲੇ ਠੰਢੇ ਸਿੰਕ ਦੇ ਵਿਚਕਾਰ ਕੰਮ ਕਰਦਾ ਹੈ। ਜੇਕਰ ਇੰਜਣ ਸਰੋਤ ਤੋਂ ਪ੍ਰਤੀ ਚੱਕਰ 1200 J ਤਾਪ ਸੋਖਦਾ ਹੈ, ਤਾਂ ਇਹ ਪ੍ਰਤੀ ਚੱਕਰ ਕਿੰਨਾ ਮਕੈਨੀਕਲ ਕਾਰਜ (W) ਕਰਦਾ ਹੈ ਅਤੇ ਇਸਦੀ ਤਾਪ ਕੁਸ਼ਲਤਾ (η) ਕੀ ਹੈ?",
      "hi": "एक उत्क्रमणीय कार्नो इंजन 327°C के तप्त स्रोत और 27°C के शीत सिंक के बीच कार्य करता है। यदि इंजन स्रोत से प्रति चक्र 1200 J ऊष्मा अवशोषित करता है, तो वह प्रति चक्र कितना यांत्रिक कार्य (W) करता है तथा उसकी दक्षता (η) क्या है?"
    },
    "options": {
      "A": {
        "en": "W = 800 J, η = 66.7%",
        "pa": "W = 800 J, η = 66.7%",
        "hi": "W = 800 J, η = 66.7%"
      },
      "B": {
        "en": "W = 600 J, η = 50%",
        "pa": "W = 600 J, η = 50%",
        "hi": "W = 600 J, η = 50%"
      },
      "C": {
        "en": "W = 400 J, η = 33.3%",
        "pa": "W = 400 J, η = 33.3%",
        "hi": "W = 400 J, η = 33.3%"
      },
      "D": {
        "en": "W = 900 J, η = 75%",
        "pa": "W = 900 J, η = 75%",
        "hi": "W = 900 J, η = 75%"
      }
    },
    "correct": "B",
    "explanation": {
      "en": "Convert temperatures to Kelvin: T_H = 327 + 273 = 600 K, and T_C = 27 + 273 = 300 K. Carnot efficiency is η = 1 − (T_C / T_H) = 1 − (300 / 600) = 1 − 0.5 = 0.50 (50%). Work output per cycle is W = η × Q_H = 0.50 × 1200 J = 600 J.",
      "pa": "ਤਾਪਮਾਨ ਨੂੰ ਕੈਲਵਿਨ ਵਿੱਚ ਬਦਲਣ ਤੇ: T_H = 327 + 273 = 600 K, T_C = 27 + 273 = 300 K। ਕਾਰਨੋਟ ਕੁਸ਼ਲਤਾ η = 1 − T_C/T_H = 1 − 300/600 = 0.5 (50%)। ਕੀਤਾ ਗਿਆ ਕਾਰਜ W = η × Q_H = 0.5 × 1200 J = 600 J।",
      "hi": "तापमान को केल्विन में बदलने पर: T_H = 327 + 273 = 600 K, T_C = 27 + 273 = 300 K। कार्नो दक्षता η = 1 − T_C/T_H = 1 − 300/600 = 0.5 (50%)। किया गया कार्य W = η × Q_H = 0.5 × 1200 J = 600 J।"
    },
