      "hi": "यदि किसी आदर्श कृष्णिका (blackbody) का परम ताप T से दोगुना कर 2T कर दिया जाए, तो उसकी अधिकतम उत्सर्जन तरंगदैर्घ्य (λ_m) तथा प्रति इकाई क्षेत्रफल से उत्सर्जित कुल विकिरण क्षमता (E) में क्या परिवर्तन होगा?"
