        "pa": "ਵੀਨ ਦੇ ਨਿਯਮ ਅਨੁਸਾਰ λ_m ਦੁੱਗਣੀ (2 λ_m) ਹੋ ਜਾਂਦੀ ਹੈ, ਅਤੇ E 4 ਗੁਣਾ (4 E) ਹੋ ਜਾਂਦੀ ਹੈ",
