    "examTag": "Punjab Master Cadre Science (Level G)",
    "question": {
      "en": "From the Helmholtz free energy differential dF = −S dT − P dV (where F = U − TS), which of the following Maxwell thermodynamic relations is directly obtained by equating the mixed second partial derivatives of F?",
      "pa": "ਹੈਲਮਹੋਲਟਜ਼ ਮੁਕਤ ਊਰਜਾ ਡਿਫਰੈਂਸ਼ੀਅਲ dF = −S dT − P dV (ਜਿੱਥੇ F = U − TS) ਤੋਂ, F ਦੇ ਮਿਸ਼ਰਤ ਦੂਜੇ ਅੰਸ਼ਕ ਡੈਰੀਵੇਟਿਵਾਂ ਨੂੰ ਬਰਾਬਰ ਰੱਖ ਕੇ ਹੇਠ ਲਿਖਿਆਂ ਵਿੱਚੋਂ ਕਿਹੜਾ ਮੈਕਸਵੈੱਲ ਥਰਮੋਡਾਇਨਾਮਿਕ ਸਬੰਧ ਸਿੱਧਾ ਪ੍ਰਾਪਤ ਹੁੰਦਾ ਹੈ?",
      "hi": "हेल्महोल्ट्ज़ मुक्त ऊर्जा अवकलज dF = −S dT − P dV (जहाँ F = U − TS) से, F के मिश्रित द्वितीय आंशिक अवकलजों को बराबर करने पर निम्नलिखित में से कौन-सा मैक्सवेल ऊष्मागतिक संबंध सीधे प्राप्त होता है?"
    },
    "options": {
      "A": {
        "en": "(∂S / ∂V)_T = (∂P / ∂T)_V",
        "pa": "(∂S / ∂V)_T = (∂P / ∂T)_V",
        "hi": "(∂S / ∂V)_T = (∂P / ∂T)_V"
      },
      "B": {
        "en": "(∂T / ∂V)_S = −(∂P / ∂S)_V",
        "pa": "(∂T / ∂V)_S = −(∂P / ∂S)_V",
        "hi": "(∂T / ∂V)_S = −(∂P / ∂S)_V"
      },
      "C": {
        "en": "(∂S / ∂P)_T = −(∂V / ∂T)_P",
        "pa": "(∂S / ∂P)_T = −(∂V / ∂T)_P",
        "hi": "(∂S / ∂P)_T = −(∂V / ∂T)_P"
      },
      "D": {
        "en": "(∂T / ∂P)_S = (∂V / ∂S)_P",
        "pa": "(∂T / ∂P)_S = (∂V / ∂S)_P",
        "hi": "(∂T / ∂P)_S = (∂V / ∂S)_P"
      }
    },
    "correct": "A",
    "explanation": {
      "en": "From dF = −S dT − P dV, we have S = −(∂F/∂T)_V and P = −(∂F/∂V)_T. Since dF is an exact differential, ∂²F/(∂V∂T) = ∂²F/(∂T∂V), which directly gives (∂S/∂V)_T = (∂P/∂T)_V. (Option B comes from dU, Option C from Gibbs energy dG, and Option D from enthalpy dH).",
      "pa": "dF = −S dT − P dV ਤੋਂ, S = −(∂F/∂T)_V ਅਤੇ P = −(∂F/∂V)_T ਮਿਲਦਾ ਹੈ। ਕਿਉਂਕਿ dF ਇੱਕ ਯਥਾਰਥ ਡਿਫਰੈਂਸ਼ੀਅਲ ਹੈ, ਇਸ ਲਈ (∂S/∂V)_T = (∂P/∂T)_V ਸਿੱਧਾ ਪ੍ਰਾਪਤ ਹੁੰਦਾ ਹੈ।",
      "hi": "dF = −S dT − P dV से, S = −(∂F/∂T)_V तथा P = −(∂F/∂V)_T होता है। चूँकि dF एक यथार्थ अवकलज है, अतः मिश्रित अवकलजों की समानता से सीधे (∂S/∂V)_T = (∂P/∂T)_V प्राप्त होता है।"
    },
