    "question": {
      "en": "An air-filled parallel-plate capacitor of capacitance C₀ = 10 μF is charged to a potential difference V₀ = 40 V and then isolated (disconnected from the battery). If a dielectric slab of dielectric constant K = 4 is now completely inserted between its plates, what are the new capacitance (C), potential difference (V), and electrostatic energy stored (U)?",
      "pa": "C₀ = 10 μF ਧਾਰਿਤਾ ਵਾਲੇ ਹਵਾ ਨਾਲ ਭਰੇ ਸਮਾਨਾਂਤਰ-ਪਲੇਟ ਕੈਪੇਸੀਟਰ ਨੂੰ V₀ = 40 V ਪੁਟੈਂਸ਼ੀਅਲ ਅੰਤਰ ਤੱਕ ਚਾਰਜ ਕੀਤਾ ਜਾਂਦਾ ਹੈ ਅਤੇ ਫਿਰ ਬੈਟਰੀ ਤੋਂ ਵੱਖ ਕਰ ਦਿੱਤਾ ਜਾਂਦਾ ਹੈ। ਜੇਕਰ ਹੁਣ ਇਸਦੀਆਂ ਪਲੇਟਾਂ ਵਿਚਕਾਰ ਡਾਇਇਲੈਕਟ੍ਰਿਕ ਸਥਿਰਾਂਕ K = 4 ਵਾਲੀ ਸਲੈਬ ਪੂਰੀ ਤਰ੍ਹਾਂ ਰੱਖ ਦਿੱਤੀ ਜਾਵੇ, ਤਾਂ ਨਵੀਂ ਧਾਰਿਤਾ (C), ਪੁਟੈਂਸ਼ੀਅਲ ਅੰਤਰ (V), ਅਤੇ ਸਟੋਰ ਕੀਤੀ ਸਥਿਰ-ਬਿਜਲੀ ਊਰਜਾ (U) ਕੀ ਹੋਵੇਗੀ?",
      "hi": "C₀ = 10 μF धारिता के एक वायु-पूरित समांतर-पट संधारित्र को V₀ = 40 V विभवांतर तक आवेशित करके बैटरी से हटा दिया जाता है। यदि अब इसकी प्लेटों के बीच परावैद्युतांक K = 4 की पट्टिका पूर्णतः प्रविष्ट कर दी जाए, तो नई धारिता (C), विभवांतर (V) तथा संचित स्थिरवैद्युत ऊर्जा (U) क्या होगी?"
    },
    "options": {
      "A": {
        "en": "C = 2.5 μF, V = 160 V, and U = 32.0 mJ",
        "pa": "C = 2.5 μF, V = 160 V, ਅਤੇ U = 32.0 mJ",
        "hi": "C = 2.5 μF, V = 160 V, तथा U = 32.0 mJ"
      },
      "B": {
        "en": "C = 40 μF, V = 40 V, and U = 32.0 mJ",
        "pa": "C = 40 μF, V = 40 V, ਅਤੇ U = 32.0 mJ",
        "hi": "C = 40 μF, V = 40 V, तथा U = 32.0 mJ"
      },
      "C": {
        "en": "C = 40 μF, V = 10 V, and U = 2.0 mJ",
        "pa": "C = 40 μF, V = 10 V, ਅਤੇ U = 2.0 mJ",
        "hi": "C = 40 μF, V = 10 V, तथा U = 2.0 mJ"
      },
      "D": {
        "en": "C = 40 μF, V = 10 V, and U = 8.0 mJ",
        "pa": "C = 40 μF, V = 10 V, ਅਤੇ U = 8.0 mJ",
        "hi": "C = 40 μF, V = 10 V, तथा U = 8.0 mJ"
      }
    },
    "correct": "C",
    "explanation": {
      "en": "Since the battery is disconnected, charge Q₀ = C₀V₀ = 10 μF × 40 V = 400 μC remains conserved. Inserting K = 4 increases capacitance to C = KC₀ = 4 × 10 μF = 40 μF. New voltage V = V₀ / K = 40 V / 4 = 10 V. Initial energy U₀ = (1/2)C₀V₀² = 0.5 × 10 × 10⁻⁶ × 1600 = 8.0 mJ; new energy U = (1/2)CV² = 0.5 × 40 × 10⁻⁶ × 100 = 2.0 × 10⁻³ J = 2.0 mJ (= U₀ / K).",
      "pa": "ਬੈਟਰੀ ਹਟਾਉਣ ਕਾਰਨ ਚਾਰਜ Q₀ = 400 μC ਸਥਿਰ ਰਹਿੰਦਾ ਹੈ। K = 4 ਰੱਖਣ ਤੇ C = KC₀ = 40 μF, ਨਵਾਂ ਪੁਟੈਂਸ਼ੀਅਲ V = V₀ / K = 40 / 4 = 10 V, ਅਤੇ ਨਵੀਂ ਊਰਜਾ U = (1/2)CV² = 0.5 × 40 × 10⁻⁶ × 10² = 2.0 × 10⁻³ J = 2.0 mJ।",
      "hi": "बैटरी हटाने के कारण आवेश Q₀ = 400 μC संरक्षित रहता है। K = 4 रखने पर धारिता C = KC₀ = 40 μF, नया विभव V = V₀ / K = 40 / 4 = 10 V, तथा संचित ऊर्जा U = (1/2)CV² = 0.5 × 40 × 10⁻⁶ × 10² = 2.0 × 10⁻³ J = 2.0 mJ।"
    },
