    "question": {
      "en": "A long air-core solenoid has 1000 turns per metre and carries a steady current of 2.5 A. What is the magnitude of the magnetic field (B) well inside the solenoid along its axis? (Take μ₀ = 4π × 10⁻⁷ T·m·A⁻¹)",
      "pa": "ਇੱਕ ਲੰਬੀ ਹਵਾ-ਕੋਰ ਵਾਲੀ ਸੋਲੇਨਾਇਡ ਵਿੱਚ ਪ੍ਰਤੀ ਮੀਟਰ 1000 ਫੇਰੇ ਹਨ ਅਤੇ ਇਸ ਵਿੱਚ 2.5 A ਦੀ ਸਥਿਰ ਧਾਰਾ ਵਹਿ ਰਹੀ ਹੈ। ਸੋਲੇਨਾਇਡ ਦੇ ਅੰਦਰ ਇਸਦੇ ਧੁਰੇ ਦੇ ਨਾਲ ਚੁੰਬਕੀ ਖੇਤਰ (B) ਦਾ ਪਰਿਮਾਣ ਕਿੰਨਾ ਹੈ? (μ₀ = 4π × 10⁻⁷ T·m·A⁻¹)",
      "hi": "एक लंबी वायु-क्रोड परिनालिका में प्रति मीटर 1000 फेरे हैं और इसमें 2.5 A की स्थायी धारा प्रवाहित हो रही है। परिनालिका के भीतर उसकी अक्ष पर चुंबकीय क्षेत्र (B) का परिमाण क्या है? (μ₀ = 4π × 10⁻⁷ T·m·A⁻¹)"
    },
    "options": {
      "A": {
        "en": "2π × 10⁻³ T (≈ 6.28 × 10⁻³ T)",
        "pa": "2π × 10⁻³ T (≈ 6.28 × 10⁻³ T)",
        "hi": "2π × 10⁻³ T (≈ 6.28 × 10⁻³ T)"
      },
      "B": {
        "en": "π × 10⁻³ T (≈ 3.14 × 10⁻³ T)",
        "pa": "π × 10⁻³ T (≈ 3.14 × 10⁻³ T)",
        "hi": "π × 10⁻³ T (≈ 3.14 × 10⁻³ T)"
      },
      "C": {
        "en": "0.5π × 10⁻³ T (≈ 1.57 × 10⁻³ T)",
        "pa": "0.5π × 10⁻³ T (≈ 1.57 × 10⁻³ T)",
        "hi": "0.5π × 10⁻³ T (≈ 1.57 × 10⁻³ T)"
      },
      "D": {
        "en": "4π × 10⁻³ T (≈ 1.26 × 10⁻² T)",
        "pa": "4π × 10⁻³ T (≈ 1.26 × 10⁻² T)",
        "hi": "4π × 10⁻³ T (≈ 1.26 × 10⁻² T)"
      }
    },
    "correct": "B",
    "explanation": {
      "en": "By Ampere’s Circuital Law, the magnetic field deep inside a long solenoid is B = μ₀ n I. Substituting μ₀ = 4π × 10⁻⁷ T·m/A, n = 1000 m⁻¹, and I = 2.5 A: B = (4π × 10⁻⁷) × 1000 × 2.5 = 10π × 10⁻⁴ T = π × 10⁻³ T ≈ 3.14 × 10⁻³ T.",
      "pa": "ਐਂਪੀਅਰ ਦੇ ਸਰਕਟ ਨਿਯਮ ਅਨੁਸਾਰ ਲੰਬੀ ਸੋਲੇਨਾਇਡ ਦੇ ਅੰਦਰ ਚੁੰਬਕੀ ਖੇਤਰ B = μ₀ n I ਹੁੰਦਾ ਹੈ। ਮੁੱਲ ਰੱਖਣ ਤੇ: B = (4π × 10⁻⁷) × 1000 × 2.5 = π × 10⁻³ T ≈ 3.14 × 10⁻³ T।",
      "hi": "ऐम्पियर के परिपथीय नियम से लंबी परिनालिका के भीतर चुंबकीय क्षेत्र B = μ₀ n I होता है। मान रखने पर: B = (4π × 10⁻⁷) × 1000 × 2.5 = π × 10⁻³ T ≈ 3.14 × 10⁻³ T।"
    },
