      "hi": "आइंस्टीन के प्रकाश-विद्युत समीकरण से: K_max = hν − φ₀ = 6.2 eV − 2.2 eV = 4.0 eV। चूँकि eV₀ = K_max होता है, अतः निरोधी विभव V₀ = 4.0 V है।"
