      "en": "For a non-relativistic electron accelerated through V volts, the de Broglie wavelength is λ = h / √(2m_e eV) = 12.27 / √V Å. Substituting V = 100 V: λ = 12.27 / √100 = 12.27 / 10 = 1.227 Å = 0.1227 nm.",
      "pa": "V ਵੋਲਟ ਰਾਹੀਂ ਪ੍ਰਵੇਗਿਤ ਇਲੈਕਟ੍ਰੌਨ ਲਈ ਡੀ-ਬ੍ਰੋਗਲੀ ਤਰੰਗ ਲੰਬਾਈ λ = 12.27 / √V Å ਹੁੰਦੀ ਹੈ। V = 100 V ਰੱਖਣ ਤੇ: λ = 12.27 / √100 = 1.227 Å (0.1227 nm)।",
      "hi": "V वोल्ट विभवांतर से त्वरित इलेक्ट्रॉन के लिए दे-ब्रॉग्ली तरंगदैर्घ्य λ = 12.27 / √V Å होती है। V = 100 V रखने पर: λ = 12.27 / √100 = 1.227 Å (0.1227 nm)।"
