      "hi": "एक स्थिर मुक्त इलेक्ट्रॉन द्वारा एक्स-किरणों के कॉम्पटन प्रकीर्णन में, जब प्रकीर्णित फोटॉन θ = 90° के प्रकीर्णन कोण पर प्रेक्षित होता है तो कॉम्पटन तरंगदैर्घ्य विस्थापन (Δλ = λ′ − λ) कितना होता है, और किस कोण पर Δλ अधिकतम होता है?"
