        "pa": "Δx · Δp_x ≥ ℏ/2; ਇਲੈਕਟ੍ਰੌਨ ਨੂੰ Δx ~ 10⁻¹⁴ m ਵਿੱਚ ਸੀਮਤ ਕਰਨ ਲਈ ਘੱਟੋ-ਘੱਟ ~20 MeV ਗਤਿਜ ਊਰਜਾ ਚਾਹੀਦੀ ਹੈ ਜੋ ਨਾਭਿਕ ਦੀ ਬੰਧਨ ਸਮਰੱਥਾ ਅਤੇ ਬੀਟਾ-ਕਿਰਨਾਂ ਦੀ ਊਰਜਾ (~2–3 MeV) ਤੋਂ ਕਿਤੇ ਵੱਧ ਹੈ",
