      "en": "A quantum particle of mass m confined in a 1D infinite potential well (box) of width L has a ground-state energy E₁ = 2.5 eV. What will be the energy of its second excited state (n = 3) in the same box, and what would the ground-state energy become if the box width were halved (L′ = L/2)?",
      "pa": "L ਚੌੜਾਈ ਵਾਲੇ ਇੱਕ-ਪਸਾਰੀ ਅਨੰਤ ਪੁਟੈਂਸ਼ੀਅਲ ਖੂਹ (1D box) ਵਿੱਚ ਬੰਦ m ਪੁੰਜ ਵਾਲੇ ਇੱਕ ਕੁਆਂਟਮ ਕਣ ਦੀ ਮੂਲ-ਅਵਸਥਾ (ground-state) ਊਰਜਾ E₁ = 2.5 eV ਹੈ। ਉਸੇ ਬੌਕਸ ਵਿੱਚ ਇਸਦੀ ਦੂਜੀ ਉਤੇਜਿਤ ਅਵਸਥਾ (second excited state, n = 3) ਦੀ ਊਰਜਾ ਕੀ ਹੋਵੇਗੀ, ਅਤੇ ਜੇਕਰ ਬੌਕਸ ਦੀ ਚੌੜਾਈ ਅੱਧੀ (L′ = L/2) ਕਰ ਦਿੱਤੀ ਜਾਵੇ ਤਾਂ ਮੂਲ-ਅਵਸਥਾ ਊਰਜਾ ਕਿੰਨੀ ਹੋ ਜਾਵੇਗੀ?",
      "hi": "L चौड़ाई के एकविमीय अनंत विभव कूप (1D box) में बद्ध m द्रव्यमान के एक क्वांटम कण की मूल अवस्था (ground-state) ऊर्जा E₁ = 2.5 eV है। उसी बॉक्स में इसकी द्वितीय उत्तेजित अवस्था (n = 3) की ऊर्जा क्या होगी, तथा बॉक्स की चौड़ाई आधी (L′ = L/2) करने पर मूल अवस्था ऊर्जा क्या हो जाएगी?"
