    "id": "q-mc-sci-mod-8",
    "topicId": "sci-phy-modern-quantum-nuclear",
    "subjectId": "science",
    "examId": "punjab-master-cadre-science",
    "examTag": "Punjab Master Cadre Science (Level H)",
    "question": {
      "en": "Using the empirical nuclear radius relation R = R₀ A^(1/3), what are the ratios of the nuclear radii (R₁ : R₂) and the nuclear mass densities (ρ₁ : ρ₂) of two nuclei having mass numbers A₁ = 27 and A₂ = 125?",
      "pa": "ਨਾਭਿਕੀ ਅਰਧ-ਵਿਆਸ ਸੂਤਰ R = R₀ A^(1/3) ਦੀ ਵਰਤੋਂ ਕਰਦੇ ਹੋਏ, ਪੁੰਜ ਸੰਖਿਆਵਾਂ A₁ = 27 ਅਤੇ A₂ = 125 ਵਾਲੇ ਦੋ ਨਾਭਿਕਾਂ ਦੇ ਅਰਧ-ਵਿਆਸਾਂ ਦਾ ਅਨੁਪਾਤ (R₁ : R₂) ਅਤੇ ਨਾਭਿਕੀ ਪੁੰਜ ਘਣਤਾਵਾਂ ਦਾ ਅਨੁਪਾਤ (ρ₁ : ρ₂) ਕੀ ਹੈ?",
      "hi": "नाभिकीय त्रिज्या सूत्र R = R₀ A^(1/3) का उपयोग करते हुए, द्रव्यमान संख्या A₁ = 27 तथा A₂ = 125 वाले दो नाभिकों की त्रिज्याओं का अनुपात (R₁ : R₂) तथा नाभिकीय द्रव्यमान घनत्वों का अनुपात (ρ₁ : ρ₂) क्या है?"
    },
    "options": {
      "A": {
        "en": "R₁ : R₂ = 9 : 25 and ρ₁ : ρ₂ = 1 : 1",
        "pa": "R₁ : R₂ = 9 : 25 ਅਤੇ ρ₁ : ρ₂ = 1 : 1",
        "hi": "R₁ : R₂ = 9 : 25 तथा ρ₁ : ρ₂ = 1 : 1"
      },
      "B": {
        "en": "R₁ : R₂ = 27 : 125 and ρ₁ : ρ₂ = 3 : 5",
        "pa": "R₁ : R₂ = 27 : 125 ਅਤੇ ρ₁ : ρ₂ = 3 : 5",
        "hi": "R₁ : R₂ = 27 : 125 तथा ρ₁ : ρ₂ = 3 : 5"
      },
      "C": {
        "en": "R₁ : R₂ = 3 : 5 and ρ₁ : ρ₂ = 27 : 125",
        "pa": "R₁ : R₂ = 3 : 5 ਅਤੇ ρ₁ : ρ₂ = 27 : 125",
        "hi": "R₁ : R₂ = 3 : 5 तथा ρ₁ : ρ₂ = 27 : 125"
      },
      "D": {
        "en": "R₁ : R₂ = 3 : 5 and ρ₁ : ρ₂ = 1 : 1",
        "pa": "R₁ : R₂ = 3 : 5 ਅਤੇ ρ₁ : ρ₂ = 1 : 1",
        "hi": "R₁ : R₂ = 3 : 5 तथा ρ₁ : ρ₂ = 1 : 1"
      }
    },
    "correct": "D",
    "explanation": {
      "en": "Since R = R₀ A^(1/3), R₁ / R₂ = (A₁ / A₂)^(1/3) = (27 / 125)^(1/3) = 3 / 5 = 3 : 5. Nuclear volume V = (4/3)πR³ = (4/3)πR₀³A, so nuclear density ρ = Mass / Volume = (A u) / [(4/3)πR₀³A] = 3u / (4πR₀³) ≈ 2.3 × 10¹⁷ kg/m³, which is independent of mass number A. Hence ρ₁ : ρ₂ = 1 : 1.",
      "pa": "R = R₀ A^(1/3) ਤੋਂ R₁ / R₂ = (27 / 125)^(1/3) = 3 : 5। ਨਾਭਿਕੀ ਘਣਤਾ ρ = 3m_N / (4πR₀³) ਪੁੰਜ ਸੰਖਿਆ A ਤੇ ਨਿਰਭਰ ਨਹੀਂ ਕਰਦੀ (ਸਾਰੇ ਨਾਭਿਕਾਂ ਲਈ ਸਥਿਰ ਰਹਿੰਦੀ ਹੈ), ਇਸ ਲਈ ρ₁ : ρ₂ = 1 : 1।",
      "hi": "R = R₀ A^(1/3) से R₁ / R₂ = (27 / 125)^(1/3) = 3 : 5। नाभिकीय घनत्व ρ = 3m_N / (4πR₀³) द्रव्यमान संख्या A से स्वतंत्र होता है, अतः ρ₁ : ρ₂ = 1 : 1।"
    },
