      "pa": "ਇੱਕ ਫੇਸ-ਸੈਂਟਰਡ ਕਿਊਬਿਕ (FCC) ਅਤੇ ਬੌਡੀ-ਸੈਂਟਰਡ ਕਿਊਬਿਕ (BCC) ਕ੍ਰਿਸਟਲ ਜਾਲੀ ਲਈ ਪ੍ਰਤੀ ਯੂਨਿਟ ਸੈੱਲ ਪਰਮਾਣੂਆਂ ਦੀ ਪ੍ਰਭਾਵੀ ਗਿਣਤੀ (Z), ਤਾਲਮੇਲ ਸੰਖਿਆ (CN), ਅਤੇ ਪੈਕਿੰਗ ਕੁਸ਼ਲਤਾ (packing efficiency) ਕੀ ਹਨ?",
      "hi": "फलक-केंद्रित घनीय (FCC) तथा अंतःकेंद्रित घनीय (BCC) क्रिस्टल जालक के लिए प्रति एकक कोष्ठिका प्रभावी परमाणुओं की संख्या (Z), समन्वय संख्या (CN) तथा संकुलन दक्षता (packing efficiency) क्या हैं?"
