      "pa": "FCC ਵਿੱਚ Z = 4, ਤਾਲਮੇਲ ਸੰਖਿਆ CN = 12, ਅਤੇ ਪੈਕਿੰਗ ਕੁਸ਼ਲਤਾ π/(3√2) ≈ 74% ਹੁੰਦੀ ਹੈ। BCC ਵਿੱਚ Z = 2, ਤਾਲਮੇਲ ਸੰਖਿਆ CN = 8, ਅਤੇ ਪੈਕਿੰਗ ਕੁਸ਼ਲਤਾ (√3 π)/8 ≈ 68% ਹੁੰਦੀ ਹੈ।",
