    "question": {
      "en": "Monochromatic X-rays of wavelength λ = 1.54 Å undergo first-order (n = 1) Bragg reflection from a set of parallel crystal planes at a glancing angle θ = 30°. According to Bragg’s Law (2d sin θ = nλ), what is the interplanar spacing (d) of the crystal planes?",
      "pa": "ਤਰੰਗ ਲੰਬਾਈ λ = 1.54 Å ਵਾਲੀਆਂ ਇੱਕ-ਰੰਗੀ ਐਕਸ-ਕਿਰਨਾਂ ਕ੍ਰਿਸਟਲ ਤਲਾਂ ਤੋਂ θ = 30° ਦੇ ਗਲਾਂਸਿੰਗ ਕੋਣ ਤੇ ਪਹਿਲੇ ਕ੍ਰਮ (n = 1) ਦਾ ਬ੍ਰੈਗ ਪਰਿਵਰਤਨ (Bragg reflection) ਦਿਖਾਉਂਦੀਆਂ ਹਨ। ਬ੍ਰੈਗ ਦੇ ਨਿਯਮ (2d sin θ = nλ) ਅਨੁਸਾਰ, ਕ੍ਰਿਸਟਲ ਤਲਾਂ ਦੇ ਵਿਚਕਾਰ ਦੀ ਦੂਰੀ (d) ਕਿੰਨੀ ਹੈ?",
      "hi": "तरंगदैर्घ्य λ = 1.54 Å की एकवर्णी एक्स-किरणें समांतर क्रिस्टल तलों से θ = 30° के पृष्ठसर्पी कोण (glancing angle) पर प्रथम कोटि (n = 1) का ब्रैग परावर्तन दर्शाती हैं। ब्रैग के नियम (2d sin θ = nλ) के अनुसार अंतरतलीय दूरी (d) क्या है?"
    },
    "options": {
      "A": {
        "en": "2.67 Å",
        "pa": "2.67 Å",
        "hi": "2.67 Å"
      },
      "B": {
        "en": "3.08 Å",
        "pa": "3.08 Å",
        "hi": "3.08 Å"
      },
      "C": {
        "en": "0.77 Å",
        "pa": "0.77 Å",
        "hi": "0.77 Å"
      },
      "D": {
        "en": "1.54 Å",
        "pa": "1.54 Å",
        "hi": "1.54 Å"
      }
    },
    "correct": "D",
    "explanation": {
      "en": "By Bragg’s Law, 2d sin θ = nλ. Given n = 1, λ = 1.54 Å, and θ = 30° (so sin 30° = 0.5): 2 × d × 0.5 = 1 × 1.54 Å ⇒ d = 1.54 Å.",
      "pa": "ਬ੍ਰੈਗ ਦੇ ਨਿਯਮ 2d sin θ = nλ ਅਨੁਸਾਰ, n = 1, λ = 1.54 Å ਅਤੇ sin 30° = 0.5 ਰੱਖਣ ਤੇ: 2 × d × 0.5 = 1 × 1.54 Å ⇒ d = 1.54 Å।",
      "hi": "ब्रैग के नियम 2d sin θ = nλ के अनुसार, n = 1, λ = 1.54 Å तथा sin 30° = 0.5 रखने पर: 2 × d × 0.5 = 1 × 1.54 Å ⇒ d = 1.54 Å।"
    },
