      "pa": "NAND ਅਤੇ NOR ਗੇਟਾਂ ਨੂੰ ਯੂਨੀਵਰਸਲ ਗੇਟ ਕਿਹਾ ਜਾਂਦਾ ਹੈ। ਡੀ-ਮੌਰਗਨ ਦੇ ਪ੍ਰਮੇਯ ਅਨੁਸਾਰ Y = (Ā + B̄)̄ = A̿ · B̿ = A · B (AND ਗੇਟ) ਬਣਦਾ ਹੈ।",
