    "question": {
      "en": "For what value of the constant a is the vector force field F = (2xy + z³) î + (a x² − z) ĵ + (3xz² − y) k̂ conservative (irrotational, ∇ × F = 0)?",
      "pa": "ਸਥਿਰਾਂਕ a ਦੇ ਕਿਸ ਮੁੱਲ ਲਈ ਵੈਕਟਰ ਬਲ ਖੇਤਰ F = (2xy + z³) î + (a x² − z) ĵ + (3xz² − y) k̂ ਇੱਕ ਸੁਰੱਖਿਅਤ (conservative / irrotational, ∇ × F = 0) ਖੇਤਰ ਹੈ?",
      "hi": "नियतांक a के किस मान के लिए सदिश बल क्षेत्र F = (2xy + z³) î + (a x² − z) ĵ + (3xz² − y) k̂ एक संरक्षी (अघूर्णी, ∇ × F = 0) क्षेत्र है?"
    },
    "options": {
      "A": {
        "en": "a = 2",
        "pa": "a = 2",
        "hi": "a = 2"
      },
      "B": {
        "en": "a = 1",
        "pa": "a = 1",
        "hi": "a = 1"
      },
      "C": {
        "en": "a = −1",
        "pa": "a = −1",
        "hi": "a = −1"
      },
      "D": {
        "en": "a = 3",
        "pa": "a = 3",
        "hi": "a = 3"
      }
    },
    "correct": "B",
    "explanation": {
      "en": "A vector field F = F_x î + F_y ĵ + F_z k̂ is conservative if and only if ∇ × F = 0. Specifically, the k̂-component of curl must vanish: ∂F_y/∂x − ∂F_x/∂y = 0. Here ∂F_y/∂x = ∂(ax² − z)/∂x = 2ax, and ∂F_x/∂y = ∂(2xy + z³)/∂y = 2x. Setting 2ax = 2x gives a = 1 (the î and ĵ components are also zero: −1 − (−1) = 0 and 3z² − 3z² = 0).",
      "pa": "ਇੱਕ ਸੁਰੱਖਿਅਤ (conservative) ਵੈਕਟਰ ਖੇਤਰ ਲਈ ∇ × F = 0 ਹੋਣਾ ਚਾਹੀਦਾ ਹੈ, ਜਿਸ ਤੋਂ ∂F_y/∂x = ∂F_x/∂y ਮਿਲਦਾ ਹੈ। ਇੱਥੇ ∂(ax² − z)/∂x = 2ax ਅਤੇ ∂(2xy + z³)/∂y = 2x ਹੈ। ਇਸ ਲਈ 2ax = 2x ⇒ a = 1।",
      "hi": "एक संरक्षी (conservative) सदिश क्षेत्र के लिए ∇ × F = 0 होना आवश्यक है, जिससे ∂F_y/∂x = ∂F_x/∂y होता है। यहाँ ∂(ax² − z)/∂x = 2ax तथा ∂(2xy + z³)/∂y = 2x है। अतः 2ax = 2x ⇒ a = 1।"
    },
