    "question": {
      "en": "Two eigenvalues of a 3 × 3 matrix A are λ₁ = 2 and λ₂ = 3. If the trace of matrix A is Tr(A) = 9 and the determinant of matrix A shows det(A) = 24, what is the third eigenvalue (λ₃), and what is the trace of A²?",
      "pa": "ਇੱਕ 3 × 3 ਮੈਟ੍ਰਿਕਸ A ਦੇ ਦੋ ਆਈਗਨ-ਮੁੱਲ λ₁ = 2 ਅਤੇ λ₂ = 3 ਹਨ। ਜੇਕਰ ਮੈਟ੍ਰਿਕਸ A ਦਾ ਟ੍ਰੇਸ Tr(A) = 9 ਹੈ ਅਤੇ ਇਸਦਾ ਡਿਟਰਮੀਨੈਂਟ det(A) = 24 ਹੈ, ਤਾਂ ਤੀਜਾ ਆਈਗਨ-ਮੁੱਲ (λ₃) ਕੀ ਹੈ, ਅਤੇ ਮੈਟ੍ਰਿਕਸ A² ਦਾ ਟ੍ਰੇਸ Tr(A²) ਕਿੰਨਾ ਹੋਵੇਗਾ?",
      "hi": "एक 3 × 3 आव्यूह A के दो आइगेनमान λ₁ = 2 और λ₂ = 3 हैं। यदि आव्यूह A का ट्रेस Tr(A) = 9 तथा सारणिक det(A) = 24 है, तो तीसरा आइगेनमान (λ₃) क्या है, और A² का ट्रेस Tr(A²) क्या होगा?"
    },
    "options": {
      "A": {
        "en": "λ₃ = 4 and Tr(A²) = 24",
        "pa": "λ₃ = 4 ਅਤੇ Tr(A²) = 24",
        "hi": "λ₃ = 4 तथा Tr(A²) = 24"
      },
      "B": {
        "en": "λ₃ = 4 and Tr(A²) = 81",
        "pa": "λ₃ = 4 ਅਤੇ Tr(A²) = 81",
        "hi": "λ₃ = 4 तथा Tr(A²) = 81"
      },
      "C": {
        "en": "λ₃ = 6 and Tr(A²) = 49",
        "pa": "λ₃ = 6 ਅਤੇ Tr(A²) = 49",
        "hi": "λ₃ = 6 तथा Tr(A²) = 49"
      },
      "D": {
        "en": "λ₃ = 4 and Tr(A²) = 29",
        "pa": "λ₃ = 4 ਅਤੇ Tr(A²) = 29",
        "hi": "λ₃ = 4 तथा Tr(A²) = 29"
      }
    },
    "correct": "D",
    "explanation": {
      "en": "For any square matrix, the sum of eigenvalues equals the trace: λ₁ + λ₂ + λ₃ = Tr(A) ⇒ 2 + 3 + λ₃ = 9 ⇒ λ₃ = 4 (which also satisfies det(A) = λ₁λ₂λ₃ = 2 × 3 × 4 = 24). The eigenvalues of A² are λ₁², λ₂², λ₃², so Tr(A²) = 2² + 3² + 4² = 4 + 9 + 16 = 29.",
      "pa": "ਕਿਸੇ ਵੀ ਵਰਗ ਮੈਟ੍ਰਿਕਸ ਲਈ ਆਈਗਨ-ਮੁੱਲਾਂ ਦਾ ਜੋੜ ਟ੍ਰੇਸ ਦੇ ਬਰਾਬਰ ਹੁੰਦਾ ਹੈ: λ₁ + λ₂ + λ₃ = 9 ⇒ 2 + 3 + λ₃ = 9 ⇒ λ₃ = 4 (ਅਤੇ 2 × 3 × 4 = 24)। A² ਦੇ ਆਈਗਨ-ਮੁੱਲ λ₁², λ₂², λ₃² ਹੁੰਦੇ ਹਨ, ਇਸ ਲਈ Tr(A²) = 2² + 3² + 4² = 4 + 9 + 16 = 29।",
      "hi": "किसी भी वर्ग आव्यूह के आइगेनमानों का योग उसके ट्रेस के बराबर होता है: λ₁ + λ₂ + λ₃ = 9 ⇒ 2 + 3 + λ₃ = 9 ⇒ λ₃ = 4 (तथा गुणनफल 2 × 3 × 4 = 24 = det(A))। A² के आइगेनमान λ₁², λ₂², λ₃² होते हैं, अतः Tr(A²) = 2² + 3² + 4² = 4 + 9 + 16 = 29।"
    },
