        "hi": "टी.ओ. डाइनर (T.O. Diener); वाइरॉइड बिना किसी प्रोटीन आवरण (कैप्सिड) के केवल कम अणुभार वाले मुक्त एकल-रज्जुक वृत्ताकार RNA से बने होते हैं"
