      "pa": "ਟੀ.ਓ. ਡਾਇਨਰ (T.O. Diener) ਨੇ 1971 ਵਿੱਚ ਵਾਇਰੌਇਡਜ਼ ਦੀ ਖੋਜ ਕੀਤੀ, ਜੋ ਆਲੂ ਦੇ ਸਪਿੰਡਲ ਟਿਊਬਰ ਰੋਗ ਦਾ ਕਾਰਨ ਬਣਦੇ ਹਨ। ਇਹਨਾਂ ਵਿੱਚ ਪ੍ਰੋਟੀਨ ਕੋਟ (capsid) ਨਹੀਂ ਹੁੰਦਾ ਅਤੇ ਇਹ ਸਿਰਫ਼ ਘੱਟ ਅਣੂ-ਭਾਰ ਵਾਲੇ ਮੁਕਤ RNA ਤੋਂ ਬਣੇ ਹੁੰਦੇ ਹਨ।",
