    "id": "q-mc-sci-bot1-4",
    "topicId": "sci-bio-diversity-plant-structural",
    "subjectId": "science",
    "examId": "punjab-master-cadre-science",
    "examTag": "Punjab Master Cadre Science (Level G)",
    "question": {
      "en": "Suppose a Gymnosperm (Pinus) and an Angiosperm (Zea mays) both have a somatic root-tip chromosome number of 2n = 24. What will be the chromosome numbers in the nutritive endosperm cells of the Gymnosperm and the Angiosperm respectively?",
      "pa": "ਮੰਨ ਲਓ ਕਿ ਇੱਕ ਜਿਮਨੋਸਪਰਮ (Pinus) ਅਤੇ ਇੱਕ ਐਂਜੀਓਸਪਰਮ (Zea mays) ਦੋਵਾਂ ਦੇ ਜੜ੍ਹ-ਸਿਰੇ ਦੇ ਕਾਇਕ ਸੈੱਲਾਂ ਵਿੱਚ ਕ੍ਰੋਮੋਸੋਮ ਸੰਖਿਆ 2n = 24 ਹੈ। ਜਿਮਨੋਸਪਰਮ ਅਤੇ ਐਂਜੀਓਸਪਰਮ ਦੇ ਭਰੂਣ-ਪੋਸ਼ (endosperm) ਸੈੱਲਾਂ ਵਿੱਚ ਕ੍ਰਮਵਾਰ ਕ੍ਰੋਮੋਸੋਮ ਸੰਖਿਆ ਕਿੰਨੀ ਹੋਵੇਗੀ?",
      "hi": "मान लीजिए कि एक अनावृतबीजी (Pinus) और एक आवृतबीजी (Zea mays) दोनों की मूलाग्र कायिक कोशिकाओं में गुणसूत्र संख्या 2n = 24 है। अनावृतबीजी और आवृतबीजी के भ्रूणपोष (endosperm) की कोशिकाओं में क्रमशः गुणसूत्र संख्या क्या होगी?"
    },
    "options": {
      "A": {
        "en": "Gymnosperm endosperm = 24 (diploid, 2n); Angiosperm endosperm = 36 (triploid, 3n)",
        "pa": "ਜਿਮਨੋਸਪਰਮ ਭਰੂਣ-ਪੋਸ਼ = 24 (2n); ਐਂਜੀਓਸਪਰਮ ਭਰੂਣ-ਪੋਸ਼ = 36 (3n)",
        "hi": "अनावृतबीजी भ्रूणपोष = 24 (2n); आवृतबीजी भ्रूणपोष = 36 (3n)"
      },
      "B": {
        "en": "Gymnosperm endosperm = 36 (triploid, 3n); Angiosperm endosperm = 12 (haploid, n)",
        "pa": "ਜਿਮਨੋਸਪਰਮ ਭਰੂਣ-ਪੋਸ਼ = 36 (3n); ਐਂਜੀਓਸਪਰਮ ਭਰੂਣ-ਪੋਸ਼ = 12 (n)",
        "hi": "अनावृतबीजी भ्रूणपोष = 36 (3n); आवृतबीजी भ्रूणपोष = 12 (n)"
      },
      "C": {
        "en": "Both have 36 chromosomes (triploid, 3n)",
        "pa": "ਦੋਵਾਂ ਵਿੱਚ 36 ਕ੍ਰੋਮੋਸੋਮ (ਤ੍ਰਿਗੁਣਿਤ, 3n) ਹੋਣਗੇ",
        "hi": "दोनों में 36 गुणसूत्र (त्रिगुणित, 3n) होंगे"
      },
      "D": {
        "en": "Gymnosperm endosperm = 12 (haploid, n, pre-fertilization); Angiosperm endosperm = 36 (triploid, 3n, post-fertilization)",
        "pa": "ਜਿਮਨੋਸਪਰਮ ਭਰੂਣ-ਪੋਸ਼ = 12 (ਅਗੁਣਿਤ, n, ਨਿਸ਼ੇਚਨ ਤੋਂ ਪਹਿਲਾਂ); ਐਂਜੀਓਸਪਰਮ ਭਰੂਣ-ਪੋਸ਼ = 36 (ਤ੍ਰਿਗੁਣਿਤ, 3n, ਨਿਸ਼ੇਚਨ ਤੋਂ ਬਾਅਦ)",
        "hi": "अनावृतबीजी भ्रूणपोष = 12 (अगुणित, n, निषेचन-पूर्व); आवृतबीजी भ्रूणपोष = 36 (त्रिगुणित, 3n, निषेचन-पश्चात)"
      }
    },
    "correct": "D",
    "explanation": {
      "en": "Given 2n = 24, the haploid number is n = 12. In Gymnosperms (Pinus, Cycas), the endosperm is the female gametophyte formed BEFORE fertilization, so it is haploid: n = 12 chromosomes. In Angiosperms, the primary endosperm nucleus (PEN) is formed AFTER double fertilization (triple fusion: 2n polar nuclei + n male gamete = 3n), so it is triploid: 3n = 3 × 12 = 36 chromosomes.",
      "pa": "2n = 24 ਹੋਣ ਤੇ n = 12 ਹੈ। ਜਿਮਨੋਸਪਰਮਾਂ ਵਿੱਚ ਭਰੂਣ-ਪੋਸ਼ ਨਿਸ਼ੇਚਨ ਤੋਂ ਪਹਿਲਾਂ ਬਣਦਾ ਹੈ ਅਤੇ ਅਗੁਣਿਤ (n = 12) ਹੁੰਦਾ ਹੈ। ਐਂਜੀਓਸਪਰਮਾਂ ਵਿੱਚ ਭਰੂਣ-ਪੋਸ਼ ਤੀਹਰੇ ਸੰਯੋਜਨ (triple fusion) ਨਾਲ ਨਿਸ਼ੇਚਨ ਤੋਂ ਬਾਅਦ ਬਣਦਾ ਹੈ ਅਤੇ ਤ੍ਰਿਗੁਣਿਤ (3n = 3 × 12 = 36) ਹੁੰਦਾ ਹੈ।",
      "hi": "2n = 24 होने पर n = 12 है। अनावृतबीजियों (Gymnosperms) में भ्रूणपोष निषेचन से पूर्व मादा युग्मकोद्भिद से बनता है, अतः अगुणित (n = 12) होता है। आवृतबीजियों (Angiosperms) में भ्रूणपोष त्रिसंलयन (triple fusion) से निषेचन के पश्चात बनता है, अतः त्रिगुणित (3n = 3 × 12 = 36) होता है।"
    },
