      "pa": "ਸਾਈਕਸ (Cycas) ਵਿੱਚ ਸਾਇਨੋਬੈਕਟੀਰੀਆ (Anabaena/Nostoc) ਨਾਲ ਸਹਿਜੀਵੀ ਕੋਰਾਲਾਇਡ ਜੜ੍ਹਾਂ (coralloid roots) ਹੁੰਦੀਆਂ ਹਨ ਅਤੇ ਨਰ ਤੇ ਮਾਦਾ ਪੌਦੇ ਵੱਖ-ਵੱਖ (dioecious) ਹੁੰਦੇ ਹਨ। ਪਾਈਨਸ (Pinus) ਵਿੱਚ ਉੱਲੀ ਨਾਲ ਮਾਈਕੋਰਾਈਜ਼ਾ (mycorrhiza) ਹੁੰਦਾ ਹੈ ਅਤੇ ਨਰ ਤੇ ਮਾਦਾ ਸ਼ੰਕੂ ਇੱਕੋ ਰੁੱਖ ਤੇ (monoecious) ਲੱਗਦੇ ਹਨ।",
