      "en": "In a dicot stem, vascular bundles are arranged in a ring and are conjoint, collateral, and open (intrafascicular cambium present) with endarch protoxylem (protoxylem towards pith/centre). In a dicot root, xylem and phloem occur on separate radii (radial arrangement, typically diarch to tetrarch, 2–4 patches) with exarch protoxylem (protoxylem towards periphery/pericycle).",
      "pa": "ਦੋ-ਬੀਜਪੱਤਰੀ ਤਣੇ (dicot stem) ਵਿੱਚ ਸੰਵਹਿਣ ਪੂਲ ਇੱਕ ਰਿੰਗ ਵਿੱਚ ਹੁੰਦੇ ਹਨ, ਜੋ ਸੰਯੁਕਤ (conjoint), ਖੁੱਲ੍ਹੇ (ਕੈਂਬੀਅਮ ਸਮੇਤ) ਅਤੇ ਐਂਡਾਰਕ (endarch — ਪ੍ਰੋਟੋਜ਼ਾਇਲਮ ਕੇਂਦਰ ਵੱਲ) ਹੁੰਦੇ ਹਨ। ਦੋ-ਬੀਜਪੱਤਰੀ ਜੜ੍ਹ ਵਿੱਚ ਰੇਡੀਅਲ (radial, 2–4 ਸਮੂਹ) ਅਤੇ ਐਗਜ਼ਾਰਕ (exarch — ਪ੍ਰੋਟੋਜ਼ਾਇਲਮ ਬਾਹਰ ਵੱਲ) ਵਿਵਸਥਾ ਹੁੰਦੀ ਹੈ।",
      "hi": "द्विबीजपत्री तने में संवहन बंडल एक वलय में व्यवस्थित, संयुक्त, खुले (एधा युक्त) तथा मध्यादिदारुक (endarch — प्रोटोजाइलम केंद्र की ओर) होते हैं। द्विबीजपत्री मूल में संवहन बंडल अरीय (radial, 2–4 समूह) तथा बाह्यादिदारुक (exarch — प्रोटोजाइलम परिधि की ओर) होते हैं।"
