      "hi": "आवृतबीजियों में \"द्विनिषेचन\" (Double Fertilization — 1898 में Lilium और Fritillaria में) की खोज किसने की, इसमें कौन-सी दो संलयन घटनाएँ सम्मिलित हैं, तथा कौन-सी संरचना पराग नलिका को सहाय कोशिका में निर्देशित करती है?"
