      "pa": "ਸਰਗੇਈ ਨਵਾਸ਼ਚਿਨ (1898) ਨੇ Lilium ਅਤੇ Fritillaria ਵਿੱਚ ਦੋਹਰੇ ਨਿਸ਼ੇਚਨ ਦੀ ਖੋਜ ਕੀਤੀ। ਸਿਨਰਜਿਡ ਦਾ ਫਿਲੀਫਾਰਮ ਉਪਕਰਣ (Filiform apparatus) ਪਰਾਗ ਨਲੀ ਨੂੰ ਰਾਹ ਦਿਖਾਉਂਦਾ ਹੈ, ਅਤੇ ਸਿੰਗੈਮੀ (2n ਯੁਗਮਜ) + ਤੀਹਰਾ ਸੰਯੋਜਨ (3n PEN) ਮਿਲ ਕੇ ਦੋਹਰਾ ਨਿਸ਼ੇਚਨ ਅਖਵਾਉਂਦੇ ਹਨ।",
