    "correct": "A",
    "explanation": {
      "en": "In the C₃ Calvin cycle, fixing 1 CO₂ requires 3 ATP (2 in reduction + 1 in RuBP regeneration) and 2 NADPH; thus 6 CO₂ (1 glucose) requires 6 × 3 = 18 ATP and 6 × 2 = 12 NADPH. In C₄ plants, regenerating PEP from pyruvate by pyruvate phosphate dikinase (PPDK) in mesophyll cells consumes 2 extra ATP per CO₂ (12 extra ATP for 6 CO₂), totaling 18 + 12 = 30 ATP and 12 NADPH per glucose.",
      "pa": "C₃ ਕੈਲਵਿਨ ਚੱਕਰ ਵਿੱਚ 1 CO₂ ਲਈ 3 ATP ਅਤੇ 2 NADPH ਲੱਗਦੇ ਹਨ, ਇਸ ਲਈ 1 ਗਲੂਕੋਜ਼ (6 CO₂) ਲਈ 18 ATP ਅਤੇ 12 NADPH ਖਰਚ ਹੁੰਦੇ ਹਨ। C₄ ਪੌਦਿਆਂ ਵਿੱਚ PEP ਦੇ ਪੁਨਰ-ਨਿਰਮਾਣ ਲਈ ਪ੍ਰਤੀ CO₂ 2 ਵਾਧੂ ATP ਲੱਗਦੇ ਹਨ, ਇਸ ਲਈ ਕੁੱਲ 30 ATP ਅਤੇ 12 NADPH ਖਰਚ ਹੁੰਦੇ ਹਨ।",
      "hi": "C₃ कैल्विन चक्र में प्रति CO₂ 3 ATP और 2 NADPH लगते हैं, अतः 1 ग्लूकोज़ (6 CO₂) के लिए 18 ATP और 12 NADPH खर्च होते हैं। C₄ पादपों में पर्णमध्योतक में PEP के पुनर्जनन हेतु प्रति CO₂ 2 अतिरिक्त ATP लगते हैं, अतः कुल 30 ATP और 12 NADPH खर्च होते हैं।"
    },
