      "D": {
        "en": "Cobalt-Nickel (Co-Ni) complex; Leghemoglobin synthesizes the 16 ATP molecules needed per N₂ fixed",
        "pa": "ਕੋਬਾਲਟ-ਨਿਕਲ (Co-Ni) ਪ੍ਰੋਟੀਨ; ਲੈਗਹੀਮੋਗਲੋਬਿਨ 16 ATP ਅਣੂਆਂ ਦਾ ਨਿਰਮਾਣ ਕਰਦਾ ਹੈ",
        "hi": "कोबाल्ट-निकेल (Co-Ni) संकुल; लेगहीमोग्लोबिन प्रति N₂ आवश्यक 16 ATP अणुओं का संश्लेषण करता है"
      }
