    "correct": "C",
    "explanation": {
      "en": "Nitrogenase is a Mo-Fe (Molybdenum-Iron) protein complex (consisting of dinitrogenase MoFe-protein and dinitrogenase reductase Fe-protein) that requires 8 ATP per NH₃ (16 ATP per N₂ molecule). Because Nitrogenase is irreversibly inactivated by molecular oxygen (O₂), legume root nodules contain pink Leghemoglobin, which functions as an \"oxygen scavenger\" (oxygen buffer) to maintain microaerophilic/anaerobic conditions around the bacteroids.",
      "pa": "ਨਾਈਟ੍ਰੋਜਨੇਜ਼ ਇੱਕ Mo-Fe (ਮੌਲੀਬਡੇਨਮ-ਆਇਰਨ) ਪ੍ਰੋਟੀਨ ਐਂਜ਼ਾਈਮ ਹੈ ਜੋ 1 N₂ ਤੋਂ 2 NH₃ ਬਣਾਉਣ ਲਈ 16 ATP (ਪ੍ਰਤੀ NH₃ 8 ATP) ਵਰਤਦਾ ਹੈ। ਕਿਉਂਕਿ ਨਾਈਟ੍ਰੋਜਨੇਜ਼ ਆਕਸੀਜਨ (O₂) ਪ੍ਰਤੀ ਬਹੁਤ ਸੰਵੇਦਨਸ਼ੀਲ ਹੈ, ਗੰਢਾਂ ਵਿੱਚ ਮੌਜੂਦ ਗੁਲਾਬੀ ਲੈਗਹੀਮੋਗਲੋਬਿਨ \"ਆਕਸੀਜਨ-ਸਕੈਵੇਂਜਰ\" ਵਜੋਂ ਕੰਮ ਕਰਕੇ ਆਕਸੀਜਨ-ਮੁਕਤ ਵਾਤਾਵਰਣ ਬਣਾਈ ਰੱਖਦਾ ਹੈ।",
      "hi": "नाइट्रोजनेज़ एक Mo-Fe (मॉलिब्डेनम-आयरन) प्रोटीन एंजाइम है जो 1 N₂ से 2 NH₃ बनाने में 16 ATP (प्रति NH₃ 8 ATP) खर्च करता है। चूँकि नाइट्रोजनेज़ आणविक ऑक्सीजन (O₂) से निष्क्रिय हो जाता है, मूल ग्रंथिकाओं में उपस्थित गुलाबी लेगहीमोग्लोबिन \"ऑक्सीजन अपमार्जक\" (oxygen scavenger) का कार्य कर अवायवीय स्थिति बनाए रखता है।"
    },
