    "question": {
      "en": "Which of the following correctly lists all six (6) Wetlands of International Importance (Ramsar Sites) located in Punjab, along with the wetland at the confluence of the Beas and Sutlej rivers famous for the endangered Indus River Dolphin (Platanista minor)?",
      "pa": "ਹੇਠ ਲਿਖਿਆਂ ਵਿੱਚੋਂ ਕਿਹੜਾ ਵਿਕਲਪ ਪੰਜਾਬ ਵਿੱਚ ਸਥਿਤ ਸਾਰੀਆਂ ਛੇ (6) ਅੰਤਰਰਾਸ਼ਟਰੀ ਮਹੱਤਵ ਵਾਲੀਆਂ ਰਾਮਸਰ ਜਲਗਾਹਾਂ (Ramsar Wetlands) ਨੂੰ ਸਹੀ ਦਰਸਾਉਂਦਾ ਹੈ, ਅਤੇ ਦੱਸਦਾ ਹੈ ਕਿ ਬਿਆਸ ਅਤੇ ਸਤਲੁਜ ਦਰਿਆਵਾਂ ਦੇ ਸੰਗਮ ਤੇ ਸਥਿਤ ਕਿਹੜੀ ਜਲਗਾਹ/ਦਰਿਆਈ ਖੇਤਰ ਦੁਰਲੱਭ ਸਿੰਧੂ ਡੌਲਫਿਨ (Platanista minor) ਲਈ ਪ੍ਰਸਿੱਧ ਹੈ?",
      "hi": "निम्नलिखित में से कौन-सा विकल्प पंजाब में स्थित सभी छह (6) अंतर्राष्ट्रीय महत्व की रामसर आर्द्रभूमियों (Ramsar Sites) को सही सूचीबद्ध करता है, और व्यास व सतलुज नदियों के संगम एवं सिंधु डॉल्फ़िन (Platanista minor) के संरक्षण क्षेत्र की पहचान करता है?"
    },
    "options": {
      "A": {
        "en": "Keoladeo, Sambhar, Harike, Kanjli, Ropar, and Chandra Taal",
        "pa": "ਕੇਵਲਾਦੇਵ, ਸਾਂਭਰ, ਹਰੀਕੇ, ਕਾਂਜਲੀ, ਰੋਪੜ, ਅਤੇ ਚੰਦਰ ਤਾਲ",
        "hi": "केवलादेव, सांभर, हरिके, कांजली, रोपड़ तथा चंद्र ताल"
      },
      "B": {
        "en": "Sukhna Lake, Harike, Kanjli, Ropar, Sultanpur, and Pong Dam",
        "pa": "ਸੁਖਨਾ ਝੀਲ, ਹਰੀਕੇ, ਕਾਂਜਲੀ, ਰੋਪੜ, ਸੁਲਤਾਨਪੁਰ, ਅਤੇ ਪੌਂਗ ਡੈਮ",
        "hi": "सुखना झील, हरिके, कांजली, रोपड़, सुल्तानपुर तथा पोंग बांध"
      },
      "C": {
        "en": "Harike, Ranjit Sagar, Siswan, Kanjli, Ropar, and Renuka Wetland",
        "pa": "ਹਰੀਕੇ, ਰਣਜੀਤ ਸਾਗਰ, ਸਿਸਵਾਂ, ਕਾਂਜਲੀ, ਰੋਪੜ, ਅਤੇ ਰੇਣੁਕਾ ਜਲਗਾਹ",
        "hi": "हरिके, रणजीत सागर, सिसवां, कांजली, रोपड़ तथा रेणुका आर्द्रभूमि"
      },
      "D": {
        "en": "Harike, Kanjli, Ropar, Keshopur-Miani, Nangal, and Beas Conservation Reserve; Harike lies at the Beas-Sutlej confluence and Beas Conservation Reserve hosts the Indus River Dolphin and reintroduced Gharial",
        "pa": "ਹਰੀਕੇ, ਕਾਂਜਲੀ, ਰੋਪੜ, ਕੇਸ਼ੋਪੁਰ-ਮਿਆਣੀ, ਨੰਗਲ, ਅਤੇ ਬਿਆਸ ਕੰਜ਼ਰਵੇਸ਼ਨ ਰਿਜ਼ਰਵ; ਹਰੀਕੇ ਬਿਆਸ-ਸਤਲੁਜ ਸੰਗਮ ਤੇ ਹੈ ਅਤੇ ਬਿਆਸ ਕੰਜ਼ਰਵੇਸ਼ਨ ਰਿਜ਼ਰਵ ਸਿੰਧੂ ਡੌਲਫਿਨ ਤੇ ਘੜਿਆਲ ਲਈ ਪ੍ਰਸਿੱਧ ਹੈ",
        "hi": "हरिके, कांजली, रोपड़, केशोपुर-मियानी, नंगल तथा व्यास कंजर्वेशन रिजर्व; हरिके व्यास-सतलुज संगम पर है तथा व्यास कंजर्वेशन रिजर्व सिंधु डॉल्फ़िन व घड़ियाल के लिए प्रसिद्ध है"
      }
    },
    "correct": "D",
    "explanation": {
      "en": "Punjab has 6 designated Ramsar Wetlands: (1) Harike Wetland (1990, Tarn Taran/Ferozepur/Kapurthala at the confluence of Beas and Sutlej rivers), (2) Kanjli Wetland (2002, Kali Bein in Kapurthala associated with Guru Nanak Dev Ji), (3) Ropar Wetland (2002, Sutlej River in Rupnagar), (4) Keshopur-Miani Community Reserve (2019, Gurdaspur), (5) Nangal Wildlife Sanctuary (2019, Sutlej in Rupnagar), and (6) Beas Conservation Reserve (2019, 185 km stretch of Beas river hosting India’s only population of Indus River Dolphin Platanista minor and reintroduced Gharial).",
      "pa": "ਪੰਜਾਬ ਵਿੱਚ ਕੁੱਲ 6 ਰਾਮਸਰ ਜਲਗਾਹਾਂ (Ramsar Sites) ਹਨ: (1) ਹਰੀਕੇ ਪੱਤਣ (1990, ਬਿਆਸ-ਸਤਲੁਜ ਸੰਗਮ), (2) ਕਾਂਜਲੀ (2002, ਕਾਲੀ ਵੇਈਂ, ਕਪੂਰਥਲਾ), (3) ਰੋਪੜ (2002, ਸਤਲੁਜ), (4) ਕੇਸ਼ੋਪੁਰ-ਮਿਆਣੀ (2019, ਗੁਰਦਾਸਪੁਰ), (5) ਨੰਗਲ (2019, ਰੂਪਨਗਰ), ਅਤੇ (6) ਬਿਆਸ ਕੰਜ਼ਰਵੇਸ਼ਨ ਰਿਜ਼ਰਵ (2019, ਜਿੱਥੇ ਸਿੰਧੂ ਦਰਿਆਈ ਡੌਲਫਿਨ Platanista minor ਅਤੇ ਘੜਿਆਲ ਪਾਏ ਜਾਂਦੇ ਹਨ)।",
      "hi": "पंजाब में कुल 6 रामसर आर्द्रभूमियाँ हैं: (1) हरिके पत्तन (1990, व्यास-सतलुज संगम), (2) कांजली (2002, काली बेईं, कपूरथला), (3) रोपड़ (2002, सतलुज), (4) केशोपुर-मियानी (2019, गुरदासपुर), (5) नंगल (2019, रूपनगर), तथा (6) व्यास कंजर्वेशन रिजर्व (2019, जहाँ लुप्तप्राय सिंधु नदी डॉल्फ़िन Platanista minor और घड़ियाल संरक्षित हैं)।"
    },
