        "pa": "ਪਲੈਟੀਹੈਲਮਿੰਥੀਜ਼: ਨੈਫਰੀਡੀਆ; ਐਸਕੇਹੈਲਮਿੰਥੀਜ਼: ਕੌਕਸਲ ਗ੍ਰੰਥੀਆਂ; ਆਰਥਰੋਪੋਡਾ: ਪ੍ਰੋਬੋਸਿਸ ਗ੍ਰੰਥੀ; ਇਕਾਈਨੋਡਰਮੇਟਾ: ਰੈਡੂਲਾ",
        "hi": "प्लैटीहेल्मिन्थीज़: वृक्कक; एस्केहेल्मिन्थीज़: कॉक्सल ग्रंथियाँ; आर्थ्रोपोडा: शुंड ग्रंथि; इकाइनोडर्मेटा: रेडुला"
