      "en": "In the human alimentary canal, which gastric mucosal cells secrete hydrochloric acid (HCl) and Castle’s intrinsic factor (essential for absorption of Vitamin B₁₂ / cyanocobalamin to prevent pernicious anaemia), and which brush-border duodenal enzyme activates pancreatic trypsinogen into active trypsin?",
      "pa": "ਮਨੁੱਖੀ ਪਾਚਨ ਪ੍ਰਣਾਲੀ ਵਿੱਚ, ਮਿਹਦੇ ਦੀਆਂ ਕਿਹੜੀਆਂ ਸੈੱਲਾਂ ਹਾਈਡ੍ਰੋਕਲੋਰਿਕ ਤੇਜ਼ਾਬ (HCl) ਅਤੇ ਕੈਸਲ ਦਾ ਅੰਦਰੂਨੀ ਕਾਰਕ (Castle’s intrinsic factor — ਵਿਟਾਮਿਨ B₁₂ ਦੇ ਸੋਖਣ ਲਈ ਜ਼ਰੂਰੀ) ਪੈਦਾ ਕਰਦੀਆਂ ਹਨ, ਅਤੇ ਛੋਟੀ ਆਂਦਰ ਦਾ ਕਿਹੜਾ ਐਂਜ਼ਾਈਮ ਪੈਨਕ੍ਰੀਆਟਿਕ ਟ੍ਰਿਪਸੀਨੋਜਨ ਨੂੰ ਸਰਗਰਮ ਟ੍ਰਿਪਸਿਨ ਵਿੱਚ ਬਦਲਦਾ ਹੈ?",
