      "pa": "ਮਿਹਦੇ ਦੀਆਂ ਪੈਰੀਏਟਲ ਜਾਂ ਔਕਸਿੰਟਿਕ (Oxyntic) ਸੈੱਲਾਂ HCl ਅਤੇ ਕੈਸਲ ਦਾ ਅੰਦਰੂਨੀ ਕਾਰਕ (ਵਿਟਾਮਿਨ B₁₂ ਦੇ ਸੋਖਣ ਲਈ ਜ਼ਰੂਰੀ) ਪੈਦਾ ਕਰਦੀਆਂ ਹਨ, ਜਦਕਿ ਚੀਫ਼ (ਪੈਪਟਿਕ) ਸੈੱਲਾਂ ਪੈਪਸੀਨੋਜਨ ਪੈਦਾ ਕਰਦੀਆਂ ਹਨ। ਛੋਟੀ ਆਂਦਰ ਦੇ ਮਿਊਕੋਸਾ ਤੋਂ ਨਿਕਲਣ ਵਾਲਾ ਐਂਟਰੋਕਾਈਨੇਜ਼ (Enterokinase) ਐਂਜ਼ਾਈਮ ਟ੍ਰਿਪਸੀਨੋਜਨ ਨੂੰ ਸਰਗਰਮ ਟ੍ਰਿਪਸਿਨ ਵਿੱਚ ਬਦਲਦਾ ਹੈ।",
