    "correct": "A",
    "explanation": {
      "en": "Stroke Volume SV = EDV − ESV = 130 mL − 60 mL = 70 mL/beat. Cardiac Output CO = SV × Heart Rate = 70 mL/beat × 75 beats/min = 5,250 mL/min = 5.25 L/min. In an Electrocardiogram (ECG): the P-wave represents atrial depolarization, the QRS complex represents ventricular depolarization (which triggers ventricular contraction/systole shortly after Q), and the T-wave represents ventricular repolarization (return to normal state).",
      "pa": "ਸਟ੍ਰੋਕ ਆਇਤਨ SV = EDV − ESV = 130 − 60 = 70 mL। ਕਾਰਡੀਅਕ ਆਊਟਪੁੱਟ CO = SV × HR = 70 × 75 = 5,250 mL/min = 5.25 L/min। ECG ਵਿੱਚ P-ਤਰੰਗ ਐਟਰੀਆ ਦਾ ਡੀਪੋਲਰਾਈਜ਼ੇਸ਼ਨ, QRS ਕੰਪਲੈਕਸ ਵੈਂਟ੍ਰੀਕਲਾਂ ਦਾ ਡੀਪੋਲਰਾਈਜ਼ੇਸ਼ਨ, ਅਤੇ T-ਤਰੰਗ ਵੈਂਟ੍ਰੀਕਲਾਂ ਦਾ ਰੀਪੋਲਰਾਈਜ਼ੇਸ਼ਨ ਦਰਸਾਉਂਦੀ ਹੈ।",
      "hi": "प्रवाह आयतन SV = EDV − ESV = 130 − 60 = 70 mL। हृद निकास CO = SV × HR = 70 × 75 = 5,250 mL/min = 5.25 L/min। ECG में P-तरंग अलिंदों का अध्रुवण, QRS सम्मिश्र निलयों का अध्रुवण (depolarization), तथा T-तरंग निलयों का पुनःध्रुवण (repolarization) दर्शाती है।"
    },
