    "examTag": "Punjab Master Cadre Science (Level H)",
    "question": {
      "en": "According to the Sliding Filament Theory of skeletal muscle contraction (Huxley & Hanson), which protein subunit binds Ca²⁺ ions released from the sarcoplasmic reticulum to unmask active binding sites on actin, and what happens to the lengths of the A-band, I-band, and H-zone during contraction?",
      "pa": "ਪਿੰਜਰ ਮਾਸਪੇਸ਼ੀ ਦੇ ਸੁੰਗੜਨ ਦੇ ਸਲਾਈਡਿੰਗ ਫਿਲਾਮੈਂਟ ਸਿਧਾਂਤ (Sliding Filament Theory) ਅਨੁਸਾਰ, ਸਾਰਕੋਪਲਾਜ਼ਮਿਕ ਰੈਟੀਕੁਲਮ ਤੋਂ ਨਿਕਲਣ ਵਾਲੇ Ca²⁺ ਆਇਨ ਕਿਸ ਪ੍ਰੋਟੀਨ ਉਪ-ਇਕਾਈ ਨਾਲ ਜੁੜ ਕੇ ਐਕਟਿਨ ਤੇ ਸਰਗਰਮ ਸਥਾਨਾਂ ਨੂੰ ਖੋਲ੍ਹਦੇ ਹਨ, ਅਤੇ ਸੁੰਗੜਨ ਦੌਰਾਨ A-ਬੈਂਡ, I-ਬੈਂਡ ਅਤੇ H-ਜ਼ੋਨ ਦੀ ਲੰਬਾਈ ਤੇ ਕੀ ਪ੍ਰਭਾਵ ਪੈਂਦਾ ਹੈ?",
      "hi": "कंकाल पेशी संकुचन के सर्पी तंतु सिद्धांत (Sliding Filament Theory) के अनुसार, सार्कोप्लाज्मिक रेटिकुलम से मुक्त Ca²⁺ आयन किस प्रोटीन उप-इकाई से जुड़कर एक्टिन पर सक्रिय स्थलों को अनावृत करते हैं, और संकुचन के दौरान A-बैंड, I-बैंड तथा H-क्षेत्र (H-zone) की लंबाई में क्या परिवर्तन होता है?"
    },
    "options": {
      "A": {
        "en": "Ca²⁺ binds to Tropomyosin directly; both A-band and I-band shorten equally",
        "pa": "Ca²⁺ ਸਿੱਧਾ ਟ੍ਰੋਪੋਮਾਇਓਸਿਨ ਨਾਲ ਜੁੜਦਾ ਹੈ; A-ਬੈਂਡ ਅਤੇ I-ਬੈਂਡ ਦੋਵੇਂ ਬਰਾਬਰ ਛੋਟੇ ਹੁੰਦੇ ਹਨ",
        "hi": "Ca²⁺ सीधे ट्रोपोमायोसिन से जुड़ता है; A-बैंड और I-बैंड दोनों समान रूप से छोटे होते हैं"
      },
      "B": {
        "en": "Ca²⁺ binds to Myosin heavy meromyosin (HMM); the A-band shortens while the I-band and H-zone remain constant",
        "pa": "Ca²⁺ ਮਾਇਓਸਿਨ HMM ਨਾਲ ਜੁੜਦਾ ਹੈ; A-ਬੈਂਡ ਛੋਟਾ ਹੋ ਜਾਂਦਾ ਹੈ ਜਦਕਿ I-ਬੈਂਡ ਅਤੇ H-ਜ਼ੋਨ ਸਥਿਰ ਰਹਿੰਦੇ ਹਨ",
        "hi": "Ca²⁺ मायोसिन HMM से जुड़ता है; A-बैंड छोटा हो जाता है जबकि I-बैंड और H-क्षेत्र अपरिवर्तित रहते हैं"
      },
      "C": {
        "en": "Ca²⁺ binds to Troponin-C (TpC); the A-band retains its constant length, whereas the I-band, H-zone, and overall sarcomere (between Z-lines) shorten",
        "pa": "Ca²⁺ ਟ੍ਰੋਪੋਨਿਨ-C (Troponin-C) ਨਾਲ ਜੁੜਦਾ ਹੈ; A-ਬੈਂਡ ਦੀ ਲੰਬਾਈ ਸਥਿਰ (constant) ਰਹਿੰਦੀ ਹੈ, ਜਦਕਿ I-ਬੈਂਡ, H-ਜ਼ੋਨ ਅਤੇ ਸਾਰਕੋਮੀਅਰ ਛੋਟੇ ਹੋ ਜਾਂਦੇ ਹਨ",
        "hi": "Ca²⁺ ट्रोपोनिन-C (Troponin-C) से जुड़ता है; A-बैंड की लंबाई अपरिवर्तित (नियत) रहती है, जबकि I-बैंड, H-क्षेत्र और सार्कोमियर छोटे हो जाते हैं"
      },
      "D": {
        "en": "Ca²⁺ binds to Calmodulin in skeletal muscle; the I-band lengthens while the A-band disappears",
        "pa": "Ca²⁺ ਕੈਲਮੋਡੁਲਿਨ ਨਾਲ ਜੁੜਦਾ ਹੈ; I-ਬੈਂਡ ਲੰਬਾ ਹੋ ਜਾਂਦਾ ਹੈ ਜਦਕਿ A-ਬੈਂਡ ਖਤਮ ਹੋ ਜਾਂਦਾ ਹੈ",
        "hi": "Ca²⁺ कैलमोडुलिन से जुड़ता है; I-बैंड लंबा हो जाता है जबकि A-बैंड लुप्त हो जाता है"
      }
    },
    "correct": "C",
    "explanation": {
      "en": "In skeletal muscle contraction, acetylcholine release at the neuromuscular junction triggers Ca²⁺ release from the sarcoplasmic reticulum. Ca²⁺ binds to the Troponin-C (TpC) subunit on thin filaments, shifting tropomyosin to expose myosin-binding sites on F-actin. As thin (actin) filaments slide inward over thick (myosin) filaments toward the M-line, the Z-lines come closer (sarcomere shortens), the I-band and H-zone shorten (or disappear at maximal contraction), while the length of the anisotropic A-band remains strictly CONSTANT.",
      "pa": "ਮਾਸਪੇਸ਼ੀ ਸੁੰਗੜਨ ਦੌਰਾਨ Ca²⁺ ਆਇਨ ਪਤਲੇ ਤੰਤੂਆਂ ਤੇ ਮੌਜੂਦ ਟ੍ਰੋਪੋਨਿਨ-C (Troponin-C) ਨਾਲ ਜੁੜਦੇ ਹਨ, ਜਿਸ ਨਾਲ ਐਕਟਿਨ ਤੇ ਮਾਇਓਸਿਨ ਦੇ ਜੁੜਨ ਵਾਲੇ ਸਥਾਨ ਖੁੱਲ੍ਹ ਜਾਂਦੇ ਹਨ। ਸੁੰਗੜਨ ਸਮੇਂ I-ਬੈਂਡ, H-ਜ਼ੋਨ ਅਤੇ ਸਾਰਕੋਮੀਅਰ ਛੋਟੇ ਹੋ ਜਾਂਦੇ ਹਨ, ਪਰ A-ਬੈਂਡ ਦੀ ਲੰਬਾਈ ਬਿਲਕੁਲ ਸਥਿਰ (constant) ਰਹਿੰਦੀ ਹੈ।",
      "hi": "पेशी संकुचन के दौरान Ca²⁺ आयन पतले तंतुओं के ट्रोपोनिन-C (Troponin-C) उप-इकाई से जुड़ते हैं, जिससे एक्टिन पर मायोसिन बंधन स्थल खुल जाते हैं। संकुचन के समय I-बैंड, H-क्षेत्र और सार्कोमियर छोटे हो जाते हैं, परंतु A-बैंड की लंबाई पूर्णतः अपरिवर्तित (constant) रहती है।"
    },
