    "question": {
      "en": "In a resting neuron (resting membrane potential ≈ −70 mV), how does the electrogenic Sodium-Potassium ATPase pump (Na⁺/K⁺ pump) transport ions across the axonal membrane per ATP hydrolyzed, and what ion flux causes the rapid depolarization phase (+30 to +45 mV) of an action potential?",
      "pa": "ਇੱਕ ਵਿਰਾਮ ਅਵਸਥਾ ਵਾਲੇ ਨਿਊਰੌਨ (resting potential ≈ −70 mV) ਵਿੱਚ, ਸੋਡੀਅਮ-ਪੋਟਾਸ਼ੀਅਮ ਪੰਪ (Na⁺/K⁺ ATPase) ਪ੍ਰਤੀ ATP ਅਣੂ ਆਇਨਾਂ ਨੂੰ ਝਿੱਲੀ ਦੇ ਆਰ-ਪਾਰ ਕਿਵੇਂ ਭੇਜਦਾ ਹੈ, ਅਤੇ ਐਕਸ਼ਨ ਪੁਟੈਂਸ਼ੀਅਲ ਦੇ ਤੇਜ਼ ਡੀਪੋਲਰਾਈਜ਼ੇਸ਼ਨ ਪੜਾਅ (+30 ਤੋਂ +45 mV) ਦਾ ਕਾਰਨ ਕਿਹੜੇ ਆਇਨਾਂ ਦਾ ਪ੍ਰਵਾਹ ਹੈ?",
      "hi": "विराम अवस्था वाले तंत्रिकाक्ष (resting potential ≈ −70 mV) में, सोडियम-पोटैशियम पंप (Na⁺/K⁺ ATPase) प्रति ATP जल-अपघटन पर आयनों का परिवहन कैसे करता है, तथा क्रिया विभव (action potential) के तीव्र अध्रुवण (depolarization) प्रावस्था का कारण कौन-सा आयन प्रवाह है?"
    },
