      "en": "In a regular 28-day human menstrual cycle, which mid-cycle hormonal event triggers the rupture of the mature Graafian follicle to release the secondary oocyte (ovulation on day ~14), and what is the primary hormone secreted by the resulting Corpus Luteum to maintain the endometrium?",
      "pa": "ਮਨੁੱਖੀ 28-ਦਿਨਾਂ ਦੇ ਮਾਹਵਾਰੀ ਚੱਕਰ ਵਿੱਚ, ਚੱਕਰ ਦੇ ਵਿਚਕਾਰ (~14ਵੇਂ ਦਿਨ) ਕਿਹੜੀ ਹਾਰਮੋਨਲ ਘਟਨਾ ਪਰਿਪੱਕ ਗ੍ਰਾਫੀਅਨ ਫੌਲੀਕਲ ਦੇ ਫਟਣ ਅਤੇ ਸੈਕੰਡਰੀ ਓਸਾਈਟ ਦੇ ਨਿਕਲਣ (ਅੰਡ-ਉਤਸਰਜਨ / ovulation) ਦਾ ਕਾਰਨ ਬਣਦੀ ਹੈ, ਅਤੇ ਇਸ ਤੋਂ ਬਾਅਦ ਬਣੇ ਕਾਰਪਸ ਲਿਊਟੀਅਮ (Corpus Luteum) ਦੁਆਰਾ ਬੱਚੇਦਾਨੀ ਦੀ ਅੰਦਰੂਨੀ ਪਰਤ (endometrium) ਨੂੰ ਬਣਾਈ ਰੱਖਣ ਲਈ ਕਿਹੜਾ ਮੁੱਖ ਹਾਰਮੋਨ ਪੈਦਾ ਕੀਤਾ ਜਾਂਦਾ ਹੈ?",
